#include "ui_draw.h"
#include <cmath>
#include <algorithm>
#include "font_vec.h"
namespace tz {
namespace {
// Text is drawn from vector glyphs (src/ui/font_vec.h, generated by tools/gen_font_vec.py from Poppins, SIL OFL): filled
// triangles inset by half a pixel plus a one-pixel alpha-faded fringe along every contour = anti-aliased edges with no
// texture, shader or renderer change. `bold` (UIDraw::chunky) selects the Bold weight for titles.
struct VFont { const VecGlyph* g; const int16_t* v; const int8_t* n; const uint16_t* t; const uint16_t* c; };
const VFont kMed{VF_M_G, VF_M_V, VF_M_N, VF_M_T, VF_M_C}, kBold{VF_B_G, VF_B_V, VF_B_N, VF_B_T, VF_B_C};
inline int glyphIndex(unsigned char ch) { return (ch >= 32 && ch < 127) ? ch - 32 : '?' - 32; }
inline float emOf(float scale) { return 12.f * scale; }
void pushTri(RenderList& rl, float ax, float ay, Color ac, float bx, float by, Color bc, float cx, float cy, Color cc) {
  if ((bx - ax) * (cy - ay) - (by - ay) * (cx - ax) < 0) { std::swap(bx, cx); std::swap(by, cy); std::swap(bc, cc); }  // same winding as UIDraw::rect
  rl.ui.push_back(UIVertex{ax, ay, ac.r, ac.g, ac.b, ac.a}); rl.ui.push_back(UIVertex{bx, by, bc.r, bc.g, bc.b, bc.a}); rl.ui.push_back(UIVertex{cx, cy, cc.r, cc.g, cc.b, cc.a});
}
void emitGlyph(RenderList& rl, const VFont& F, int gi, float ox, float oy, float em, Color c, bool aa, bool bold) {
  const VecGlyph& G = F.g[gi]; if (!G.nt) return;
  float base = oy + VF_BASELINE * em, k = em / VF_Q;
  float stem = (bold ? 0.13f : 0.088f) * em, f = aa ? std::max(0.45f, std::min(1.0f, 0.75f * stem)) : 0.f;   // fringe width (px), thinner on tiny/thin strokes
  static std::vector<float> P; P.resize((size_t)G.nv * 2);
  for (int i = 0; i < G.nv; i++) {
    float x = ox + F.v[(G.v0 + i) * 2] * k, y = base + F.v[(G.v0 + i) * 2 + 1] * k;
    if (aa) { x -= F.n[(G.v0 + i) * 2] / VF_NORM * f * 0.5f; y -= F.n[(G.v0 + i) * 2 + 1] / VF_NORM * f * 0.5f; }   // inset: the fringe puts the visual edge back on the outline
    P[(size_t)i * 2] = x; P[(size_t)i * 2 + 1] = y;
  }
  for (int i = 0; i < G.nt; i++) {
    const uint16_t* t = F.t + (G.t0 + i) * 3;
    pushTri(rl, P[t[0] * 2], P[t[0] * 2 + 1], c, P[t[1] * 2], P[t[1] * 2 + 1], c, P[t[2] * 2], P[t[2] * 2 + 1], c);
  }
  if (!aa) return;
  Color z = c; z.a = 0;
  const uint16_t* cp = F.c + G.c0;
  for (int ci = 0; ci < G.nc; ci++) {
    int len = cp[0]; const uint16_t* ix = cp + 1;
    for (int j = 0; j < len; j++) {
      int a = ix[j], b = ix[(j + 1) % len];
      float ax = P[a * 2], ay = P[a * 2 + 1], bx = P[b * 2], by = P[b * 2 + 1];
      float ox2 = ax + F.n[(G.v0 + a) * 2] / VF_NORM * f, oy2 = ay + F.n[(G.v0 + a) * 2 + 1] / VF_NORM * f;
      float px2 = bx + F.n[(G.v0 + b) * 2] / VF_NORM * f, py2 = by + F.n[(G.v0 + b) * 2 + 1] / VF_NORM * f;
      pushTri(rl, ax, ay, c, bx, by, c, px2, py2, z);
      pushTri(rl, ax, ay, c, px2, py2, z, ox2, oy2, z);
    }
    cp += 1 + len;
  }
}
}  // namespace
UIDraw::UIDraw(RenderList& r) : rl(r), W((float)r.width), H((float)r.height) {
  s = std::max(1.0f, std::round(H / 720.f * 2.f * 2.f) / 2.f);  // 2 at 720p, 3 at 1080p (half steps in between)
  if (r.uiScale > 0) s = r.uiScale;
}
void UIDraw::rect(float x, float y, float w, float h, Color c) {
  UIVertex a{x, y, c.r, c.g, c.b, c.a}, b{x + w, y, c.r, c.g, c.b, c.a}, d{x, y + h, c.r, c.g, c.b, c.a}, e{x + w, y + h, c.r, c.g, c.b, c.a};
  rl.ui.push_back(a); rl.ui.push_back(b); rl.ui.push_back(d); rl.ui.push_back(b); rl.ui.push_back(e); rl.ui.push_back(d);
}
void UIDraw::rectGrad(float x, float y, float w, float h, Color tl, Color tr, Color bl, Color br) {
  UIVertex a{x, y, tl.r, tl.g, tl.b, tl.a}, b{x + w, y, tr.r, tr.g, tr.b, tr.a}, d{x, y + h, bl.r, bl.g, bl.b, bl.a}, e{x + w, y + h, br.r, br.g, br.b, br.a};
  rl.ui.push_back(a); rl.ui.push_back(b); rl.ui.push_back(d); rl.ui.push_back(b); rl.ui.push_back(e); rl.ui.push_back(d);
}
void UIDraw::frame(float x, float y, float w, float h, Color c, float t) { rect(x, y, w, t, c); rect(x, y + h - t, w, t, c); rect(x, y, t, h, c); rect(x + w - t, y, t, h, c); }
void UIDraw::star(float cx, float cy, float r, Color c) {
  for (int i = 0; i < 5; i++) {
    float a0 = -PI / 2 + i * 2 * PI / 5, a1 = a0 + PI / 5, a2 = a0 - PI / 5, ri = r * 0.45f;
    UIVertex o{cx, cy, c.r, c.g, c.b, c.a}, p{cx + std::cos(a0) * r, cy + std::sin(a0) * r, c.r, c.g, c.b, c.a};
    UIVertex q{cx + std::cos(a1) * ri, cy + std::sin(a1) * ri, c.r, c.g, c.b, c.a}, w{cx + std::cos(a2) * ri, cy + std::sin(a2) * ri, c.r, c.g, c.b, c.a};
    rl.ui.push_back(o); rl.ui.push_back(p); rl.ui.push_back(q); rl.ui.push_back(o); rl.ui.push_back(w); rl.ui.push_back(p);
  }
}
void UIDraw::tri(float x1, float y1, float x2, float y2, float x3, float y3, Color c) {
  rl.ui.push_back({x1, y1, c.r, c.g, c.b, c.a}); rl.ui.push_back({x2, y2, c.r, c.g, c.b, c.a}); rl.ui.push_back({x3, y3, c.r, c.g, c.b, c.a});
}
void UIDraw::kaijuHead(float cx, float cy, float r, Color c, Color eye) {
  Color dark{c.r * 0.35f, c.g * 0.35f, c.b * 0.35f, c.a}, tooth{1.f, 1.f, 0.95f, c.a};
  // back spikes
  tri(cx - r * 0.75f, cy - r * 0.2f, cx - r * 0.45f, cy - r * 0.95f, cx - r * 0.1f, cy - r * 0.55f, c);
  tri(cx - r * 0.2f, cy - r * 0.7f, cx + r * 0.05f, cy - r * 1.25f, cx + r * 0.35f, cy - r * 0.6f, c);
  tri(cx + r * 0.2f, cy - r * 0.55f, cx + r * 0.6f, cy - r * 1.0f, cx + r * 0.8f, cy - r * 0.15f, c);
  // skull + snout (two quads as triangles)
  tri(cx - r * 0.8f, cy - r * 0.3f, cx + r * 0.7f, cy - r * 0.6f, cx + r * 0.9f, cy + r * 0.05f, c);
  tri(cx - r * 0.8f, cy - r * 0.3f, cx + r * 0.9f, cy + r * 0.05f, cx - r * 0.6f, cy + r * 0.6f, c);
  // jaw
  tri(cx - r * 0.6f, cy + r * 0.6f, cx + r * 0.9f, cy + r * 0.05f, cx + r * 0.75f, cy + r * 0.55f, dark);
  // teeth
  for (int i = 0; i < 3; i++) { float tx = cx + r * (0.0f + 0.27f * i); tri(tx, cy + r * 0.12f, tx + r * 0.16f, cy + r * 0.12f, tx + r * 0.08f, cy + r * 0.42f, tooth); }
  // angry eye
  tri(cx + r * 0.05f, cy - r * 0.4f, cx + r * 0.55f, cy - r * 0.25f, cx + r * 0.1f, cy - r * 0.05f, eye);
}
float UIDraw::textW(const std::string& t, float scale) const {
  const VFont& F = chunky ? kBold : kMed; float em = emOf(scale), w = 0, best = 0;
  for (unsigned char ch : t) { if (ch == '\n') { best = std::max(best, w); w = 0; continue; } w += F.g[glyphIndex(ch)].adv / VF_Q * em; }
  return std::max(best, w);
}
void UIDraw::text(float x, float y, const std::string& t, float scale, Color c, bool shadow) {
  const VFont& F = chunky ? kBold : kMed; float em = emOf(scale);
  if (shadow) {   // soft drop shadow: fill only (no fringe), a little offset down-right
    Color sc{0, 0, 0, c.a * 0.55f}; float sx = x + scale * 0.8f, sy = y + scale * 0.8f, cx = sx;
    for (unsigned char ch : t) { if (ch == '\n') { cx = sx; sy += lineH(scale); continue; } int g = glyphIndex(ch); emitGlyph(rl, F, g, cx, sy, em, sc, false, chunky); cx += F.g[g].adv / VF_Q * em; }
  }
  float cx = x;
  for (unsigned char ch : t) {
    if (ch == '\n') { cx = x; y += lineH(scale); continue; }
    int g = glyphIndex(ch); emitGlyph(rl, F, g, cx, y, em, c, true, chunky); cx += F.g[g].adv / VF_Q * em;
  }
}
std::vector<std::string> UIDraw::wrap(const std::string& t, float maxW, float scale) const {
  std::vector<std::string> out; float minW = textW("MMMM", scale); maxW = std::max(maxW, minW);
  size_t start = 0;
  while (start <= t.size()) {
    size_t nl = t.find('\n', start); std::string para = t.substr(start, nl == std::string::npos ? std::string::npos : nl - start);
    std::string line; size_t i = 0;
    while (i < para.size()) {
      size_t sp = para.find(' ', i); std::string word = para.substr(i, sp == std::string::npos ? std::string::npos : sp - i);
      if (!line.empty() && textW(line + " " + word, scale) > maxW) { out.push_back(line); line.clear(); }
      while (textW(word, scale) > maxW && word.size() > 1) {   // a single over-long word: split it
        size_t n = word.size(); while (n > 1 && textW(word.substr(0, n), scale) > maxW) n--;
        out.push_back(word.substr(0, n)); word = word.substr(n);
      }
      line += (line.empty() ? "" : " ") + word;
      if (sp == std::string::npos) break; i = sp + 1;
    }
    out.push_back(line);
    if (nl == std::string::npos) break; start = nl + 1;
  }
  return out;
}
bool UIDraw::project(const Vec3& p, float& sx, float& sy) const {
  Mat4 vp = rl.view * rl.proj;
  float x = p.x * vp.m[0][0] + p.y * vp.m[1][0] + p.z * vp.m[2][0] + vp.m[3][0];
  float y = p.x * vp.m[0][1] + p.y * vp.m[1][1] + p.z * vp.m[2][1] + vp.m[3][1];
  float w = p.x * vp.m[0][3] + p.y * vp.m[1][3] + p.z * vp.m[2][3] + vp.m[3][3];
  if (w < 0.5f) return false;
  sx = (x / w * 0.5f + 0.5f) * W; sy = (1 - (y / w * 0.5f + 0.5f)) * H;
  return sx > -200 && sx < W + 200 && sy > -50 && sy < H + 50;
}
}  // namespace tz
